class ATM { long long stock[5]={};int values[5]={20,50,100,200,500};public:ATM(){}void deposit(vector<int> banknotesCount){for(int i=0;i<5;++i)stock[i]+=banknotesCount[i];}vector<int> withdraw(int amount){vector<int> take(5);int remaining=amount;for(int i=4;i>=0;--i){take[i]=min(stock[i],(long long)remaining/values[i]);remaining-=take[i]*values[i];}if(remaining)return{-1};for(int i=0;i<5;++i)stock[i]-=take[i];return take;} };
